Let $\psi:\mathbb{N}\to[0,\infty)$ be non-increasing and $k \in \mathbb{N}$.
    If 
    \[
    \sum_{n=1}^{\infty}\psi(n)(\log n)^{k-1}=\infty
    \]
    then, for almost all $({\alpha}_1,\ldots, \alpha_k) \in \mathbb R^k$, there exist infinitely many $n \in \mathbb N$ such that
\begin{equation}
\label{GallagherConc}
\| n {\alpha}_1 \| \cdots \| n {\alpha}_k \| < \psi(n).
\end{equation}

\label{BHVthm}
Let $p_1, \ldots, p_k$ be distinct primes and $\psi: \mathbb N \to [0,\infty)$ be a non-increasing function such that 
\[
\sum_{n=1}^\infty \psi(n) (\log n)^k = \infty.
\]
Then, for almost all ${\alpha} \in \mathbb R$, there exist infinitely many $n \in \mathbb N$ such that
\begin{equation}
\label{MainIneq}
|n|_{p_1} \cdots |n|_{p_k}
\| n {\alpha} \| < \psi(n).
\end{equation}

\label{MainThm}
Let $p_1, \ldots, p_k$ be distinct primes. Let $n_1, \ldots, n_k \in \mathbb Z$ and ${\gamma} \in \mathbb R$. Let $\psi: \mathbb N \to [0,\infty)$ be a non-increasing function such that 
\[
\sum_{n=1}^\infty \psi(n) (\log n)^k = \infty.
\]
Then, for almost all ${\alpha} \in \mathbb R$, there exist infinitely many $n \in \mathbb N$ such that
\begin{equation}
\label{MainIneq}
|n - n_1|_{p_1} \cdots |n - n_k|_{p_k}
\| n {\alpha} - {\gamma} \| < \psi(n).
\end{equation}

\label{WeakInhomDuff}
Let $\gamma\in \mathbb R$, and let $\Psi:\mathbb N \to [0,\infty)$ be such that 
\begin{equation}
\label{DivReq}
\sum_{n=1}^\infty \frac{\varphi(n)}{n}\Psi(n)=\infty.
\end{equation}
Then, for almost every $\alpha \in \mathbb{R}$, there exist infinitely many $n\in\mathbb N$ such that 
\[
\|n \alpha - \gamma \| <\Psi(n).
\]
